package br.com.equilibra.dashboard.api;
import br.com.equilibra.dashboard.application.DashboardQueryService; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.time.Instant;
@RestController @RequestMapping("/dashboard") @Tag(name="Dashboard",description="Resumo financeiro do usuário autenticado") @SecurityRequirement(name="bearerAuth") public class DashboardController {private final DashboardQueryService service;public DashboardController(DashboardQueryService service){this.service=service;}@GetMapping public ResponseEntity<DashboardResponse> query(@RequestParam Instant from,@RequestParam Instant to){return ResponseEntity.ok(service.query(from,to));}}
